import analysis as A, numpy as np, json

PATTERNS=['P1','P2','P3','P4','P5']
def minpat(v_plf,margin=0.95):
    for p in PATTERNS:
        if A.PHI_DECK*A.SN[p]>=v_plf/margin:
            return p
    return 'P5'

def mk(jc='JC1',nj=1,members=None,ba=None,wa=None,sp=None):
    if members is None:
        members={k:'C1' for k in ['CH-S','CH-N','CH-W','CH-E','OP-1S','OP-1N','OP-1W','OP-1E','OP-2S','OP-2N','OP-2W','OP-2E',
                                  'DR-S1','DR-S2','DR-N1','DR-N2','DR-W1','DR-W2','DR-E1','DR-E2']}
        for k in ['CH-S','CH-N','CH-W','CH-E','DR-S1','DR-S2','DR-N1','DR-N2','DR-W1','DR-W2','DR-E1','DR-E2']: members[k]='C2'
    return dict(joint_connector={w:jc for w in 'SNWE'},connectors_per_joint={w:nj for w in 'SNWE'},
      zones={f'Z{i}':'P1' for i in range(1,13)},members=members,
      base_anchor=ba or {w:'BA2' for w in 'SNWE'},wall_anchor=wa or {w:'WA1' for w in 'SNWE'},
      wall_anchor_spacing=sp or {w:8.0 for w in 'SNWE'})

def iterate(design,verbose=False,margin=0.95,defl_target=3.8,maxit=6):
    for it in range(maxit):
        sa,m,mr=A.build(design); env,R=A.envelope(sa,m,mr)
        zmax={z:max(env[c]['zone'][z] for c in env)*12000 for z in A.ZONES}
        new={z:minpat(zmax[z],margin) for z in A.ZONES}
        amp=max(env[c]['defl']['amp'] for c in env)
        changed = new!=design['zones']
        # deflection upgrade: if over target, upgrade the zones with highest shear first
        if amp>defl_target:
            order=sorted(A.ZONES,key=lambda z:-zmax[z])
            for z in order:
                if amp<=defl_target: break
                i=PATTERNS.index(new[z])
                if i<4: new[z]=PATTERNS[i+1]
        if verbose: print('it',it,'zmax',{k:round(v) for k,v in zmax.items()},'amp',round(amp,2),'zones',new)
        design['zones']=new
        if not changed and amp<=defl_target: break
    return design,sa,m,mr,env,zmax,amp

def summarize(design,sa,m,mr,env):
    segmax={w:{} for w in 'SNWE'}
    for w in 'SNWE':
        for k in env['S01']['seg'][w]:
            segmax[w][k]=max(env[c]['seg'][w][k] for c in env)
    jd={}; td={}; tdp={}
    for w in 'SNWE':
        jm=0; tm=0; worst=None
        for seg in sa[w]:
            F=segmax[w][seg['start']]
            j=max([abs(x) for x in seg['joints']]) if seg['joints'] else 0
            jm=max(jm,j*F)
            for p,(Mp,Np) in enumerate(zip(seg['moments'],seg['axials'])):
                Lp=seg['panels'][p]
                t=(abs(Mp)/(0.8*Lp*12)+abs(Np))*F
                if t>tm: tm=t; worst=(seg['start'],p,Lp)
        jd[w]=jm; td[w]=tm; tdp[w]=worst
    chord={k:max(env[c]['chord'][k] for c in env) for k in env['S01']['chord']}
    cost,area=A.cost(design)
    return dict(joint=jd,td=td,tdworst=tdp,chord=chord,cost=cost,area=area,segmax=segmax,
                wall={w:max(env[c]['wall'][w] for c in env) for w in 'SNWE'},
                defl=max(env[c]['defl']['amp'] for c in env), dwall=max(env[c]['defl']['wall'] for c in env)*A.CD/A.IE,
                zmax={z:max(env[c]['zone'][z] for c in env)*12000 for z in A.ZONES})

if __name__=='__main__':
    d=mk(); d,sa,m,mr,env,zmax,amp=iterate(d,verbose=True)
    s=summarize(d,sa,m,mr,env)
    print(json.dumps({k:(v if not isinstance(v,dict) else {kk:(round(vv,2) if isinstance(vv,(int,float,np.floating)) else vv) for kk,vv in v.items()}) for k,v in s.items()},indent=1,default=str))
    print('zones',d['zones'],'cost',s['cost'])

