def flex_zone(direction,Fpx,zone):
    """max unit shear (kip/in) in a zone from flexible beam idealisation"""
    zb=int(zone[1:])-1; xb=zb%4; yb=zb//4
    x0,x1=xb*60,(xb+1)*60; y0,y1=yb*60,(yb+1)*60
    best=0.0
    if direction=='x':
        L=180.0; w=Fpx/L
        for y in np.arange(max(y0,1),y1,2.0):
            V=w*(L/2-abs(y-L/2)); d=240.0
            for a,b,c,e in M.OPENINGS:
                if c<y<e: d-=(b-a)
            best=max(best,V/max(d,40))
    else:
        L=240.0; w=Fpx/L
        for x in np.arange(max(x0,1),x1,2.0):
            V=w*(L/2-abs(x-L/2)); d=180.0
            for a,b,c,e in M.OPENINGS:
                if a<x<b: d-=(e-c)
            best=max(best,V/max(d,40))
    return best/12.0   # kip/in

def flex_chord(direction,Fpx,line):
    if direction=='x':
        L=180.0; w=Fpx/L; best=0
        for y in np.arange(1,180,2.0):
            Mx=w*y*(L-y)/2; d=240.0
            for a,b,c,e in M.OPENINGS:
                if c<y<e: d-=(b-a)
            best=max(best,Mx/max(d,40))
        return best
    else:
        L=240.0; w=Fpx/L; best=0
        for x in np.arange(1,240,2.0):
            Mx=w*x*(L-x)/2; d=180.0
            for a,b,c,e in M.OPENINGS:
                if a<x<b: d-=(e-c)
            best=max(best,Mx/max(d,40))
        return best

def build(design):
    jk={w:(design['joint_connector'][w],design['connectors_per_joint'][w],KCON[design['joint_connector'][w]]) for w in 'SNWE'}
    sa=M.build_stageA(jk)
    zpat=design['zones']
    nodes,nid,elems=M.build_mesh(zpat)
    P=M.bar_points(nodes,nid)
    bars={}
    for k in ['CH-S','CH-N','CH-W','CH-E','OP-1S','OP-1N','OP-1W','OP-1E','OP-2S','OP-2N','OP-2W','OP-2E']:
        mark=design['members'].get(k,'C0')
        bars[k]=(P[k],AREA_M.get(mark,0.0))
    # drag strut lines: same geometry as CH lines (coincident bars)
    for k in ['DR-S1','DR-S2','DR-N1','DR-N2','DR-W1','DR-W2','DR-E1','DR-E2']:
        mark=design['members'].get(k,'C0')
        if mark=='C0': continue
        base={'DR-S1':'CH-S','DR-S2':'CH-S','DR-N1':'CH-N','DR-N2':'CH-N','DR-W1':'CH-W','DR-W2':'CH-W','DR-E1':'CH-E','DR-E2':'CH-E'}[k]
        pts=P[base]
        # trim to half length
        if k.endswith(('1','2')):
            n=len(pts); half=n//2
            pts=pts[:half] if k.endswith('1') else pts[half:]
