def deflections(m,ex,direction):
    d=ex['d']; nodes=m['nodes']; nid=m['nid']
    if direction=='x':
        comp=0; sup=(0,180)
        # support interpolated u along x
        u=np.zeros(m['nn']); 
        for q in range(m['nn']): u[q]=d[2*q]
        def supp(x,y):
            n0=nid[(int(round(x/10)),int(round(y/10)))]
            return u[n0]
        dw=0.0; dd=0.0
        for (i,j) in nid:
            node=nid[(i,j)]; x=i*10.0; y=j*10.0
            u0=u[nid[(i,0)]]; u1=u[nid[(i,NY)]]
            interp=u0+(u1-u0)*y/180.0
            dd=max(dd,abs(u[node]-interp))
            if j in (0,NY): dw=max(dw,abs(u[node]))
    else:
        u=np.zeros(m['nn'])
        for q in range(m['nn']): u[q]=d[2*q+1]
        dw=0.0; dd=0.0
        for (i,j) in nid:
            node=nid[(i,j)]; x=i*10.0; y=j*10.0
            u0=u[nid[(0,j)]]; u1=u[nid[(NX,j)]]
            interp=u0+(u1-u0)*x/240.0
            dd=max(dd,abs(u[node]-interp))
            if i in (0,NX): dw=max(dw,abs(u[node]))
    return dict(wall=dw,diaph=dd,total=dw+dd,amp=CD*(dw+dd)/IE)

CASES=[('S01','x','base',1,None),('S02','x','base',-1,None),('S03','y','base',1,None),('S04','y','base',-1,None),
       ('S05','x','base',1,('y',1)),('S06','y','base',-1,('x',-1)),
