def envelope(sa,m,mr):
    R_={}
    for direction in 'xy':
        for masscase in ['base','future']:
            for ecc in (1,-1):
                R_[(direction,masscase,ecc,'rigid')]=M.run(mr,direction,masscase,ecc,CS,rigid=True,fac=1e7)
                R_[(direction,masscase,ecc,'semi')]=M.run(m,direction,masscase,ecc,CS,rigid=False,fac=1.0)
    out={}
    for cid,dr,mc,ec,orth in CASES:
        exs=[R_[(dr,mc,ec,'rigid')],R_[(dr,mc,ec,'semi')]]
        Fpx=exs[1]['F']['Fpx']
        fac_er=0.5 if cid in ('S11','S12') else 1.0
        d=dict(zone={},wall={},seg={},chord={},Ax=0.0,F=exs[1]['F'],flex_v=0.0,flex_M=0.0)
        # flexible zone values
        fz={z:flex_zone(dr,Fpx,z) for z in ZONES}
        d['flex_v']=max(fz.values())
        for z in ZONES:
            v=max(max(e['zone'][z] for e in exs),fz[z])
            d['zone'][z]=v*fac_er
        for w in 'SNWE':
            vals=[abs(e['wallF'][w]) for e in exs]
            if (dr=='x' and w in 'SN') or (dr=='y' and w in 'WE'):
                vals.append(Fpx/2.0)  # flexible reaction on resisting wall lines
            d['wall'][w]=max(vals)*fac_er
        for w in 'SNWE':
            d['seg'][w]={}
            for k in exs[0]['segF'][w]:
                d['seg'][w][k]=max([abs(e['segF'][w][k]) for e in exs])*fac_er
        for k in exs[0]['bars']:
            d['chord'][k]=max([np.max(np.abs(e['bars'][k])) for e in exs])*fac_er
        if dr=='x':
            d['chord']['CH-W']=max(d['chord']['CH-W'],flex_chord(dr,Fpx,'CH-W')*fac_er)
            d['chord']['CH-E']=max(d['chord']['CH-E'],flex_chord(dr,Fpx,'CH-E')*fac_er)
        else:
            d['chord']['CH-S']=max(d['chord']['CH-S'],flex_chord(dr,Fpx,'CH-S')*fac_er)
            d['chord']['CH-N']=max(d['chord']['CH-N'],flex_chord(dr,Fpx,'CH-N')*fac_er)
        if orth:
            od,oe=orth
            e2s=[R_[(od,mc,oe,'rigid')],R_[(od,mc,oe,'semi')]]
            for z in ZONES:
                d['zone'][z]+=0.3*max(max(e['zone'][z] for e in e2s),flex_zone(od,e2s[1]['F']['Fpx'],z))*fac_er
            for w in 'SNWE':
                d['wall'][w]+=0.3*max([abs(e['wallF'][w]) for e in e2s])*fac_er
            for w in 'SNWE':
                for k in d['seg'][w]:
                    d['seg'][w][k]+=0.3*max([abs(e['segF'][w][k]) for e in e2s])*fac_er
            for k in d['chord']:
                d['chord'][k]+=0.3*max([np.max(np.abs(e['bars'][k])) for e in e2s])*fac_er
        d['Ax']=exs[0]['Ax']
        # deflections from semi-rigid model
        sem=exs[1]
        d['defl']=deflections(m,sem,dr)
        out[cid]=d
    return out,R_

def wall_demands(sa,env):
    """per wall line: max joint shear, max tie-down, per segment"""
    res={}
    for w in 'SNWE':
        jm=0.0; td=0.0; worst=None; segd={}
        for seg in sa[w]:
            F=env['seg'][w][seg['start']]
            j=max(abs(x) for x in seg['joints']) if seg['joints'] else 0.0
            jm=max(jm,j*F)
            # panels
            for p,(Mp,Np) in enumerate(zip(seg['moments'],seg['axials'])):
                Lp=seg['panels'][p]
                t=(abs(Mp)/(0.8*Lp*12.0)+abs(Np))*F
                if t>td: td=t; worst=(seg['start'],p)
            segd[seg['start']]=dict(F=F,joint=j*F,seg=seg)
        res[w]=dict(joint=jm,td=td,worst=worst,seg=segd)
    return res

def choose_zone_patterns(env):
    z={}
    for zz in ZONES:
        v=max(env[c]['zone'][zz] for c in env)*12000.0
        for p in ['P1','P2','P3','P4','P5']:
            if PHI_DECK*SN[p] >= v/0.90:   # 10% margin target
                z[zz]=p; break
        else: z[zz]='P5'
    return z

def cost(design):
    area={z:0 for z in ZONES}
    nodes,nid,elems=M.build_mesh(design['zones'])
    for i,j,zone in elems: area[zone]+=100
    c=sum(area[z]*RATE[design['zones'][z]] for z in ZONES)
    for k,mark in design['members'].items():
        if mark!='C0':
            L={'CH-S':240,'CH-N':240,'CH-W':180,'CH-E':180,'OP-1S':60,'OP-1N':60,'OP-1W':40,'OP-1E':40,'OP-2S':80,'OP-2N':80,'OP-2W':20,'OP-2E':20,
               'DR-S1':120,'DR-S2':120,'DR-N1':120,'DR-N2':120,'DR-W1':90,'DR-W2':90,'DR-E1':90,'DR-E2':90}[k]
            c+=L*RATE[mark]
    for w in 'SNWE':
        c+=NJOINTS[w]*design['connectors_per_joint'][w]*RATE[design['joint_connector'][w]]
        c+=NPANEL[w]*RATE[design['base_anchor'][w]]
        c+=(WLEN[w]/design['wall_anchor_spacing'][w])*RATE[design['wall_anchor'][w]]
        c+=NPANEL[w]*RATE['intermediate_precast']
    return c,area

